
function esc(v){return String(v==null?"":v).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;")}
function ago(v){if(!v)return"Not run yet";const d=new Date(v);if(isNaN(d.getTime()))return"Recently";const m=Math.max(0,Math.floor((Date.now()-d.getTime())/60000));if(m<1)return"Just now";if(m<60)return m+" min ago";const h=Math.floor(m/60);return h<24?h+" hr ago":Math.floor(h/24)+"d ago"}
function toast(msg,type){const el=document.getElementById("toast");el.textContent=msg;el.className="toast show "+(type||"");clearTimeout(window._toastT);window._toastT=setTimeout(()=>el.classList.remove("show"),3400)}
async function api(path,opts){const r=await fetch(path,opts||{});if(!r.ok){let msg="HTTP "+r.status;try{const b=await r.json();if(b.detail)msg=b.detail}catch(e){}const error=new Error(typeof msg==="string"?msg:JSON.stringify(msg));error.status=r.status;throw error}return r.json()}
const pageInfo={jobs:['Overview','Your opportunities, conversations and next steps.','Overview'],outreach:['Outreach','A thoughtful message. A meaningful next step.','Outreach'],applications:['Your pipeline','From first application to your next offer.','Pipeline'],sources:['Connections','Keep your job sources and email connected.','Connections'],settings:['Your profile','The experience and preferences behind every application.','Profile']};
function switchTab(name){if(!pageInfo[name])name='jobs';document.querySelectorAll('.tab').forEach(t=>{t.classList.toggle('active',t.dataset.tab===name);if(t.dataset.tab===name)t.setAttribute('aria-current','page');else t.removeAttribute('aria-current')});Object.keys(pageInfo).forEach(n=>document.getElementById('tab-'+n).style.display=n===name?'':'none');const info=pageInfo[name];document.getElementById('pageTitle').textContent=info[0];document.getElementById('pageDescription').textContent=info[1];document.getElementById('pageBreadcrumb').textContent=info[2];const command=document.getElementById('commandCurrent');if(command)command.textContent=info[2];if(privateConnectionReady()){if(name==='outreach')loadOutreach();if(name==='applications')loadApplications();if(name==='sources')loadSources();}history.replaceState({},'',location.pathname+location.search+'#'+name)}

const STATUS_OPTIONS=[["new","New"],["shortlisted","Shortlisted"],["saved","Saved"],["draft_ready","Draft ready"],["applied_manually","Applied"],["interview","Interview"],["rejected","Rejected"],["offer","Offer"],["closed","Closed"],["not_relevant","Not relevant"]];
function statusSelect(id,current){return '<select class="status-select" aria-label="Application status" onchange="updateStatus('+Number(id)+',this.value)">'+STATUS_OPTIONS.map(function(pair){return '<option value="'+pair[0]+'"'+(current===pair[0]?" selected":"")+'>'+pair[1]+'</option>';}).join("")+'</select>';}
async function loadStats(){if(!privateConnectionReady())return;const sequence=++statsRequestSequence,epoch=authEpoch,params=jobFilterParams();try{const s=await privateApi("/api/stats?"+params);if(sequence!==statsRequestSequence||epoch!==authEpoch||!privateConnectionReady())return;document.getElementById("statTotal").textContent=s.total_jobs??"—";document.getElementById("statNew").textContent=s.new_jobs??"—";document.getElementById("statHigh").textContent=s.high_match_jobs??"—";document.getElementById("statsWindow").textContent=s.freshness_scope==="published_checked_36h"?"Selected Gulf roles · published, checked within 36 hours":document.getElementById("filterStatus").value&&!["new"].includes(document.getElementById("filterStatus").value)?"Selected application history · all posting dates":"Selected roles · last "+(s.posted_within_days||3)+" days";const last=s.last_run;if(last&&last.finished_at){let issues="";try{const errs=typeof last.errors==="string"?JSON.parse(last.errors):last.errors;if(Array.isArray(errs)&&errs.length)issues=" · "+errs.length+" source issue"+(errs.length===1?"":"s");}catch(e){}document.getElementById("statLast").textContent=ago(last.finished_at);document.getElementById("statLastNote").textContent=(last.new_jobs||0)+" new · "+(last.fetched||0)+" fetched"+issues;document.getElementById("lastRunPill").textContent="Last run: "+ago(last.finished_at);document.getElementById("syncStatus").textContent="Synced "+ago(last.finished_at)}else{document.getElementById("statLast").textContent="Not run";document.getElementById("statLastNote").textContent="Run your first hunt"}const sourceSelect=document.getElementById("filterSource");if(sourceSelect&&s.by_source){const current=sourceSelect.value;const options=['<option value="">All sources</option>'].concat(s.by_source.map(function(row){const name=row.source||"";return '<option value="'+esc(name)+'"'+(current===name?" selected":"")+'>'+esc(name)+'</option>';}));if(current&&!s.by_source.some(row=>row.source===current))options.push('<option value="'+esc(current)+'" selected>'+esc(current)+'</option>');sourceSelect.innerHTML=options.join("");}}catch(e){if(sequence===statsRequestSequence&&epoch===authEpoch&&privateConnectionReady()){["statTotal","statNew","statHigh"].forEach(id=>document.getElementById(id).textContent="—");document.getElementById("statsWindow").textContent="Counts unavailable · retry refresh";}}}
async function loadSources(){
  if(!privateConnectionReady())return;
  try{
    const data=await privateApi("/api/sources"),sources=data.sources||[];
    const labels={working:"Working",degraded:"Degraded",missing_configuration:"Needs setup",unauthorized:"Unauthorized",rate_limited:"Rate limited",unavailable:"Unavailable",unknown:"Not checked"};
    const healthy=sources.filter(s=>s.status==="working").length;
    document.getElementById("sourceCount").textContent=healthy+"/"+sources.length+" working";
    const grid=document.getElementById("sourcesGrid");
    grid.innerHTML=sources.map(s=>{const ok=s.status==="working";return '<div class="conn-card '+(ok?"ready":"setup")+'"><div><div class="conn-name">'+esc(s.name)+'</div><div class="conn-mode">'+esc(labels[s.status]||s.status||"")+(s.detail?(" · "+esc(s.detail)):"")+'</div><div class="conn-mode">'+esc(s.connection_mode||s.type||"")+'</div></div><span class="status-badge '+(ok?"ready":"setup")+'">'+esc(labels[s.status]||"Check")+'</span></div>';}).join("")||'<div class="empty-state">No sources reported</div>';
    const portals=Object.values(data.portal_coverage||{}).filter(p=>p.market_focus);
    document.getElementById("portalCoverageGrid").innerHTML=portals.map(p=>{
      const enabled=p.discovery,statusCode=p.source_search_status||"unknown";
      const status=!enabled?"Needs setup":statusCode==="missing_configuration"?"Add SerpApi key":statusCode==="degraded"?"Partial Google search":statusCode==="working"?"Google search active":["unauthorized","rate_limited","unavailable"].includes(statusCode)?"Check Google Jobs":"Waiting for first search";
      const cardClass=enabled&&statusCode==="working"?"ready":"setup";
      const latest=p.last_hunt_checked_at?`${Number(p.last_hunt_fetched||0)} results attributed in last hunt`:"Count appears after the first hunt";
      return '<div class="conn-card '+cardClass+'"><div><div class="conn-name">'+esc(p.display_name)+'</div><div class="conn-mode">'+esc(p.market_focus)+' · Google Jobs index · '+esc(latest)+'</div><div class="conn-mode">'+esc(p.notes||"Search coverage depends on provider results.")+'</div></div><span class="status-badge '+cardClass+'">'+status+'</span></div>';
    }).join("")||'<div class="empty-state">No portal search is configured yet</div>';
    const gmail=data.gmail||{};let note=data.note||"";
    if(!gmail.connected){note+=" Gmail job-alert reading is not connected. "+(gmail.hint||"");if(gmail.callback_url)note+=" Redirect URI: "+gmail.callback_url+".";}else if(gmail.email){note+=" Gmail alerts connected as "+gmail.email+".";}
    document.getElementById("sourcesNote").textContent=note;
    window._sourceHint=sources.filter(s=>s.status&&s.status!=="working"&&s.status!=="missing_configuration").map(s=>s.name+": "+(labels[s.status]||s.status)).join("; ");
  }catch(e){toast("Could not load sources: "+e.message,"error")}
}
function jobFilterParams(){
  const params=new URLSearchParams(),status=document.getElementById('filterStatus').value;
  for(const [id,key] of [['jobSearch','q'],['filterCountry','country'],['filterScore','min_score'],['filterSource','source']]){const value=document.getElementById(id).value.trim();if(value)params.set(key,value)}
  if(gulfOpenView)params.set('gulf_open','true');
  if(status)params.set('status',status);else if(!gulfOpenView)params.set('posted_within_days',document.getElementById('filterPosted').value);
  return params;
}
let jobPage=0,jobLimit=25,statsRequestSequence=0;
async function loadJobs(reset=true){if(!privateConnectionReady())return;const requestSequence=++jobRequestSequence;if(reset)jobPage=0;loadStats();const params=jobFilterParams();params.set('limit',String(jobLimit));params.set('offset',String(jobPage*jobLimit));const body=document.getElementById('jobsBody');body.innerHTML='<tr><td colspan="6"><div class="empty-state loading">Finding your matches…</div></td></tr>';try{const data=await privateApi('/api/jobs?'+params.toString()),items=data.items||[];if(requestSequence!==jobRequestSequence)return;document.getElementById('jobCountBadge').textContent=items.length+' shown';document.getElementById('resultText').textContent=items.length?(gulfOpenView?'Published Gulf roles · requirements need review':'Ranked by match score'):'No matches in this view';document.getElementById('jobPageLabel').textContent='Page '+(jobPage+1);document.getElementById('jobPrevBtn').disabled=jobPage===0;document.getElementById('jobNextBtn').disabled=items.length<jobLimit;if(!items.length){body.innerHTML='<tr><td colspan="6"><div class="empty-state"><div class="empty-icon">⌕</div><h3>No matches in this view</h3><p>Refresh Gulf jobs for recently checked employer roles, or adjust your filters. Saved applications remain available through the status filter.</p><button class="btn btn-ghost btn-sm" onclick="switchTab(&quot;sources&quot;)">Check source health</button></div></td></tr>';return}body.innerHTML=items.map(j=>{const score=Number(j.match_score)||0,url=(String(j.url||'').startsWith('https://')||String(j.url||'').startsWith('http://'))?j.url:'#';return '<tr><td><a class="job-title" href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">'+esc(j.title)+'</a><div class="job-company">'+esc(j.company||'Company not supplied')+'</div><div class="match-reason">'+esc(j.gulf_evidence?'Published in employer feed · checked '+ago(j.gulf_evidence.checked_at):(j.match_reasons||[])[0]||'Review the original role details')+'</div></td><td><span class="location-name">'+esc(j.location||'Not supplied')+'</span><div class="job-meta">'+esc(j.country)+'</div></td><td><span class="source-label">'+esc(j.source)+'</span></td><td><span class="score-pill '+(score>=80?'high':'')+'" title="Keyword-based match heuristic">'+score+'<small>/100</small></span></td><td>'+statusSelect(j.id,j.status)+'</td><td><div class="row-actions"><button class="btn btn-small btn-primary" onclick="viewJob('+Number(j.id)+')">View &amp; apply ↗</button><button class="text-button" onclick="prepareApply('+Number(j.id)+')">Prepare draft</button><button class="text-button" onclick="startJobOutreach('+Number(j.id)+')">Find recruiter ↗</button></div></td></tr>'}).join('')}catch(e){if(requestSequence!==jobRequestSequence)return;body.innerHTML='<tr><td colspan="6"><div class="empty-state"><h3>Could not load matches</h3><p>'+esc(e.message)+'</p><button class="btn btn-ghost" onclick="loadJobs(false)">Try again</button></div></td></tr>';toast(e.message,'error')}}
function changeJobPage(direction){jobPage=Math.max(0,jobPage+direction);loadJobs(false)}
async function startJobOutreach(jobId){if(!privateConnectionReady()){switchTab('settings');toast('Connect your private profile first','error');return}switchTab('outreach');openRecruiterSearch();await loadOutreach();document.getElementById('outreachJob').value=String(jobId);document.getElementById('outreachDomain').focus()}

async function updateStatus(id,status){try{await privateApi("/api/jobs/"+id+"/status",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({status})});toast("Status updated","success");loadStats()}catch(e){toast(e.message,"error")}}

let profileReady=false,googleSessionActive=false,authEpoch=0,jobRequestSequence=0,searchWindowInitialized=false,profileSavePending=null;
const PORTAL_TOKEN_STORAGE_KEY="jobHunterPortalAccessToken";
function getPortalToken(){let token="";try{token=window.sessionStorage.getItem("jhPrivatePortalToken")||"";if(!token)token=window.localStorage.getItem(PORTAL_TOKEN_STORAGE_KEY)||"";}catch(e){}return token;}
function savePortalToken(token){googleSessionActive=false;try{window.localStorage.setItem(PORTAL_TOKEN_STORAGE_KEY,token);window.sessionStorage.removeItem("jhPrivatePortalToken");}catch(e){try{window.sessionStorage.setItem("jhPrivatePortalToken",token);}catch(_){}}}
function clearPortalToken(){try{window.localStorage.removeItem(PORTAL_TOKEN_STORAGE_KEY);window.sessionStorage.removeItem("jhPrivatePortalToken");}catch(e){}}
function privateConnectionReady(){return googleSessionActive||!!getPortalToken();}
function readCookie(name){const prefix=name+"=";const entry=document.cookie.split(";").map(x=>x.trim()).find(x=>x.startsWith(prefix));return entry?decodeURIComponent(entry.slice(prefix.length)):"";}
function resetPrivateWorkspace(){
  profileSavePending=null;
  const applyLink=document.getElementById('jobApplyLink');if(applyLink)applyLink.removeAttribute('href');
  authEpoch++; jobRequestSequence++; statsRequestSequence++; profileReady=false;searchWindowInitialized=false;
  applicationItems=[]; outreachContacts=[]; outreachDrafts=[]; outreachCurrentDraft=null; outreachVerifyId=null;
  const text=(id,value)=>{const el=document.getElementById(id);if(el)el.textContent=value};
  const html=(id,value)=>{const el=document.getElementById(id);if(el)el.innerHTML=value};
  ['profileName','profileEmail','profilePhone','profileLinkedIn','profileHeadline','profileExperience','profileSkills','targetRoles','targetCountries','targetLocations','targetSalary','targetExperience','targetDays','contactName','contactEmail','contactCompany','contactRole','contactSource','outreachDomain','outreachSubject','outreachBody','verifyNote','portalTokenInput','resumeFile','jobSearch'].forEach(id=>{const el=document.getElementById(id);if(el)el.value=''});
  ['draftDialog','jobDetailDialog','outreachVerifyDialog','outreachComposeDialog'].forEach(id=>{const el=document.getElementById(id);if(el&&el.open)el.close()});
  ['jobDetailTitle','jobDetailCompany','jobDetailEvidence','jobDetailDate','jobDetailFit','jobDetailDescription','draftTitle','draftBody','draftMeta','outreachEnvelope','outreachDraftState','verifyContactSummary'].forEach(id=>text(id,''));
  const sourceLink=document.getElementById('verifyContactSource');if(sourceLink)sourceLink.removeAttribute('href');
  ['statTotal','statNew','statHigh','statLast','applicationBadge','jobCountBadge'].forEach(id=>text(id,'—'));
  text('statLastNote','Sign in to view discovery history');text('statsWindow','Sign in to view your saved posting window');text('syncStatus','Private workspace');text('lastRunPill','Sign in to view last run');text('sourceCount','Sign in to check sources');
  text('resultText','Sign in to view job matches');text('targetRegionSummary','Sign in to view your target markets');text('jobPageLabel','Page 1');jobPage=0;
  const empty='<div class="empty-state">Sign in to view your private workspace.</div>';
  html('jobsBody','<tr><td colspan="6">'+empty+'</td></tr>');html('applicationsBody','<tr><td colspan="4">'+empty+'</td></tr>');
  ['outreachContacts','outreachQueue'].forEach(id=>html(id,'<tr><td colspan="4">'+empty+'</td></tr>'));
  ['gulfSourcesGrid','sourcesGrid','portalCoverageGrid','countryCoverage','sourceCoverage'].forEach(id=>html(id,empty));
  html('apolloResults','');html('outreachJob','<option value="">Sign in to choose a job</option>');html('filterSource','<option value="">All sources</option>');
  document.getElementById('outreachDailyLimit').value='5';document.getElementById('automationMinScore').value='80';document.getElementById('automationMaxRun').value='10';['approveEmailReview','approveEmailRelevance','verifyEmail','verifyEmployer','verifyRole'].forEach(id=>document.getElementById(id).checked=false);text('outreachGmailBtn','Enable Gmail sending');text('sourcesNote','Sign in to view your integrations.');text('outreachStatus','Sign in to manage recruiter outreach.');text('emailSetupStatus','Sign in to view email setup.');
  text('missionDiscovery','Sign in required');text('missionDiscoveryNote','Your job matches are private');text('missionResume','Sign in required');text('missionResumeNote','Your resume status is private');text('missionApply','Sign in required');text('missionApplyNote','Your application policy is private');text('missionGmail','Sign in required');text('missionGmailNote','Your connection status is private');text('missionAction','Sign in to load your private career workspace.');text('missionTimestamp','Private workspace');
  document.getElementById('profileForm').style.display='none';document.getElementById('profileConnect').style.display='';document.getElementById('profilePanel').open=true;
  ['changeTokenBtn','signOutGoogleBtn'].forEach(id=>document.getElementById(id).style.display='none');
  ['saveAutomationBtn','runAutomationBtn','autoApplyBtn','automationEnabled','uploadResumeBtn','testEmailBtn','jobPrevBtn','jobNextBtn','outreachSendBtn'].forEach(id=>document.getElementById(id).disabled=true);
  document.getElementById('filterCountry').value='';document.getElementById('filterStatus').value='';document.getElementById('targetArrangement').value='all';document.getElementById('targetVisa').value='any';document.getElementById('automationEnabled').checked=false;document.getElementById('outreachAutoApproved').checked=false;
  text('profileState','CONNECT REQUIRED');document.getElementById('profileState').className='pill setup';text('automationState','SETUP REQUIRED');document.getElementById('automationState').className='pill setup';
  text('profileSummary','Connect your private access, save your details and upload your PDF resume.');text('profileSetupNote','Sign in to manage your profile and resume.');text('resumeStatus','');text('resumeFileName','No file selected');text('automationNote','Sign in to view or change preparation rules.');
  renderWorkspaceState();
}
async function privateApi(path,opts,tokenOverride){
  const token=tokenOverride||(!googleSessionActive?getPortalToken():''),epoch=authEpoch;
  if(!token&&!googleSessionActive)throw new Error('Sign in with Google or connect with your private access key first.');
  const options={...(opts||{}),headers:{...((opts||{}).headers||{})},credentials:'same-origin'};
  if(token)options.headers.Authorization='Bearer '+token;
  else if(!['GET','HEAD','OPTIONS'].includes(String(options.method||'GET').toUpperCase())){
    const csrf=readCookie('jh_portal_csrf');if(!csrf){googleSessionActive=false;clearPortalToken();resetPrivateWorkspace();throw new Error('Your sign-in expired. Sign in with Google again.');}
    options.headers['X-JH-CSRF']=csrf;
  }
  try{const result=await api(path,options);if(epoch!==authEpoch)throw new Error('Your private connection changed. Sign in again to refresh.');return result}
  catch(e){if(e.status===401&&epoch===authEpoch){if(tokenOverride){e.message='That access key did not match. Check it and try again.';throw e}const usedGoogle=googleSessionActive;googleSessionActive=false;clearPortalToken();resetPrivateWorkspace();e.message=usedGoogle?'Your Google sign-in expired. Sign in again.':'Your saved access key is no longer valid. Enter it again above.'}throw e}
}

function showProfile(profile){const p=profile||{};document.getElementById("profileName").value=p.full_name||"";document.getElementById("profileEmail").value=p.email||"";document.getElementById("profileEmail").disabled=googleSessionActive;document.getElementById("profilePhone").value=p.phone||"";document.getElementById("profileLinkedIn").value=p.linkedin_url||"";document.getElementById("profileHeadline").value=p.headline||"";document.getElementById("profileExperience").value=p.experience_summary||"";document.getElementById("profileSkills").value=Array.isArray(p.skills)?p.skills.join(", "):"";profileReady=!!(p.full_name&&p.email&&p.has_resume);const state=document.getElementById("profileState");state.textContent=profileReady?"PROFILE READY":"PROFILE INCOMPLETE";state.className="pill "+(profileReady?"ready":"setup");document.getElementById("profileSummary").textContent=profileReady?"Your profile and resume are ready. Drafts can be prepared for your review.":"Add your name and email, then upload a PDF resume to unlock draft preparation.";document.getElementById("profileConnect").style.display="none";document.getElementById("profileForm").style.display="";document.getElementById("changeTokenBtn").style.display=googleSessionActive?"none":"";document.getElementById("signOutGoogleBtn").style.display=googleSessionActive?"":"none";document.getElementById("resumeStatus").textContent=p.resume_filename?"Uploaded: "+p.resume_filename:"No resume uploaded yet";document.getElementById("profileSetupNote").textContent=profileReady?"Ready. Draft preparation can run automatically while your policy is on. You review and submit applications yourself.":"Save your name and email, then upload a text-based PDF resume. No application is sent.";document.getElementById("saveAutomationBtn").disabled=!profileReady;document.getElementById("runAutomationBtn").disabled=!profileReady;document.getElementById("autoApplyBtn").disabled=!profileReady;}
async function loadSearchPreferences(){try{const setup=await privateApi("/api/setup"),p=setup.settings||{};document.getElementById("targetRoles").value=(p.target_titles||[]).join(", ");document.getElementById("targetCountries").value=(p.target_countries||[]).join(", ");document.getElementById("targetLocations").value=(p.preferred_locations||[]).join(", ");document.getElementById("targetSalary").value=p.min_india_salary_lpa??0;document.getElementById("targetExperience").value=p.min_experience_years??0;document.getElementById("targetArrangement").value=p.work_arrangement||"all";document.getElementById("targetVisa").value=p.visa_preference||"any";document.getElementById("targetDays").value=p.posted_within_days||3;if(!searchWindowInitialized){const days=document.getElementById("filterPosted"),value=String(p.posted_within_days||3);if(![...days.options].some(o=>o.value===value))days.add(new Option("Last "+value+" days",value));savedPostingWindow=value;if(!gulfOpenView)days.value=value;searchWindowInitialized=true;}document.getElementById("emailSetupStatus").textContent=setup.notifications.configured?"Email alerts are configured. Send a test to verify delivery. New high-match jobs will trigger an email after discovery.":"Email setup is pending. Add RESEND_API_KEY and EMAIL_TO in the service's secure settings, then send a test.";document.getElementById("testEmailBtn").disabled=!setup.notifications.configured}catch(e){document.getElementById("emailSetupStatus").textContent=e.message}}
async function saveSearchPreferences(){try{const list=id=>document.getElementById(id).value.split(",").map(x=>x.trim()).filter(Boolean);const p={target_titles:list("targetRoles"),target_countries:list("targetCountries"),preferred_locations:list("targetLocations"),min_india_salary_lpa:Number(document.getElementById("targetSalary").value),min_experience_years:Number(document.getElementById("targetExperience").value),work_arrangement:document.getElementById("targetArrangement").value,visa_preference:document.getElementById("targetVisa").value,posted_within_days:Number(document.getElementById("targetDays").value)};await privateApi("/api/settings",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(p)});toast("Search preferences saved","success");const days=document.getElementById("filterPosted");if(![...days.options].some(o=>o.value===String(p.posted_within_days)))days.add(new Option("Last "+p.posted_within_days+" days",String(p.posted_within_days)));savedPostingWindow=String(p.posted_within_days);if(!gulfOpenView)days.value=savedPostingWindow;await loadWorkspaceData()}catch(e){toast(e.message,"error")}}
async function testEmail(){try{await privateApi("/api/notify/test",{method:"POST"});toast("Test email accepted by the provider; check your inbox and spam folder","success")}catch(e){toast("Email test failed: "+e.message,"error")}}
async function connectGmail(){try{const result=await privateApi("/api/gmail/auth",{method:"POST"});window.location.assign(result.url)}catch(e){toast(e.message,"error")}}
async function connectPortal(){const input=document.getElementById("portalTokenInput"),btn=document.getElementById("connectPortalBtn"),token=(input.value||"").trim();if(!token){document.getElementById("profileConnectNote").textContent="Paste your private access key first.";input.focus();return}btn.disabled=true;btn.textContent="Connecting…";document.getElementById("profileConnectNote").textContent="Checking your private connection…";try{const p=await privateApi("/api/profile",null,token);savePortalToken(token);showProfile(p);input.value="";document.getElementById("profileConnectNote").textContent="Connected.";toast("Private profile connected","success");await loadSearchPreferences();await loadAutomationSettings();await loadWorkspaceData()}catch(e){document.getElementById("profileConnectNote").textContent=e.status===503?"Private access is not ready on the server yet. Refresh and try again shortly.":e.message;toast("Could not connect: "+e.message,"error")}finally{btn.disabled=false;btn.textContent="Connect"}}
async function disconnectWorkspace(){googleSessionActive=false;clearPortalToken();resetPrivateWorkspace();try{await api('/api/auth/logout',{method:'POST'})}catch(e){toast('Local private data cleared. Server sign-out could not be confirmed; close this browser session if using a shared device.','error')}}
async function changePortalToken(){await disconnectWorkspace();document.querySelector('#profileConnect details').open=true;document.getElementById('profileConnectNote').textContent='Enter your private access key to reconnect.';document.getElementById('portalTokenInput').focus()}
async function signOutGoogle(){await disconnectWorkspace()}

function showResumeFileName(){const file=document.getElementById("resumeFile").files[0],name=document.getElementById("resumeFileName"),upload=document.getElementById("uploadResumeBtn"),status=document.getElementById("resumeStatus");if(!file){name.textContent="No file selected";upload.disabled=true;return}name.textContent="Selected: "+file.name;if(!file.name.toLowerCase().endsWith(".pdf")){upload.disabled=true;status.textContent="Choose a PDF file.";return}if(file.size>8*1024*1024){upload.disabled=true;status.textContent="This PDF is larger than 8 MB. Choose a smaller file.";return}upload.disabled=false;status.textContent="PDF selected. Now click Step 2: Upload resume.";}
async function saveCandidateProfile(){if(!privateConnectionReady()){toast("Sign in with Google or connect with your private access key first","error");return}const btn=document.getElementById("saveProfileBtn");let pending=null;btn.disabled=true;try{const p={full_name:document.getElementById("profileName").value.trim(),email:document.getElementById("profileEmail").value.trim(),phone:document.getElementById("profilePhone").value.trim(),linkedin_url:document.getElementById("profileLinkedIn").value.trim(),headline:document.getElementById("profileHeadline").value.trim(),experience_summary:document.getElementById("profileExperience").value.trim(),skills:document.getElementById("profileSkills").value.split(",").map(x=>x.trim()).filter(Boolean)};if(!p.full_name||!p.email)throw new Error("Add your full name and email first.");pending=privateApi("/api/profile",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(p)});profileSavePending=pending;const saved=await pending;showProfile(saved);await loadAutomationSettings();toast("Profile saved","success")}catch(e){toast("Profile was not saved: "+e.message,"error")}finally{if(profileSavePending===pending)profileSavePending=null;btn.disabled=false}}
async function uploadResume(){const input=document.getElementById("resumeFile"),file=input.files[0],btn=document.getElementById("uploadResumeBtn"),status=document.getElementById("resumeStatus");if(!file){status.textContent="First choose a PDF resume.";toast("Choose your PDF resume first","error");return}if(!file.name.toLowerCase().endsWith(".pdf")||file.size>8*1024*1024){status.textContent="Choose a PDF smaller than 8 MB.";toast("Choose a PDF smaller than 8 MB","error");return}btn.disabled=true;btn.textContent="Uploading…";status.textContent="Uploading your PDF and checking that it was saved…";try{if(profileSavePending)await profileSavePending;const form=new FormData();form.append("file",file);const result=await privateApi("/api/profile/resume",{method:"POST",body:form});if(!result||result.uploaded!==true)throw new Error("The portal did not confirm the upload.");const profile=result.profile&&result.profile.has_resume?result.profile:await privateApi("/api/profile");if(!profile||!profile.has_resume)throw new Error("The portal received the file but could not confirm that the resume was saved. Keep this page open and try again.");showProfile(profile);input.value="";document.getElementById("resumeFileName").textContent="No file selected";status.textContent="Resume saved: "+(profile.resume_filename||result.filename||file.name);await loadAutomationSettings();await loadReadiness();toast("Resume saved to your Job Hunter profile","success")}catch(e){status.textContent="Upload failed: "+e.message+" The selected file is still here so you can retry.";toast("Resume upload failed: "+e.message,"error")}finally{btn.textContent="Step 2: Upload resume";btn.disabled=!input.files[0]||input.files[0].size>8*1024*1024}}
async function loadAutomationSettings(){const note=document.getElementById("automationNote");if(!privateConnectionReady()){note.textContent="Sign in with Google or connect with your private access key to view or change these rules.";document.getElementById("automationState").textContent="SETUP REQUIRED";document.getElementById("automationState").className="pill setup";document.getElementById("automationEnabled").disabled=true;document.getElementById("saveAutomationBtn").disabled=true;document.getElementById("runAutomationBtn").disabled=true;return}try{const p=await privateApi("/api/automation/settings");document.getElementById("automationEnabled").checked=!!p.enabled;document.getElementById("automationEnabled").disabled=!profileReady;document.getElementById("automationMinScore").value=p.min_score||80;document.getElementById("automationMaxRun").value=p.max_per_run||10;const state=document.getElementById("automationState");state.textContent=p.enabled?"ON · DRAFTS ONLY":"OFF · DRAFTS ONLY";state.className="pill "+(p.enabled?"ready":"setup");document.getElementById("automationPanel").open=!!profileReady&&!p.enabled;document.getElementById("saveAutomationBtn").disabled=!profileReady;document.getElementById("runAutomationBtn").disabled=!profileReady||!p.enabled;note.textContent=!profileReady?"Finish the private profile and upload a PDF resume before turning on draft preparation. Nothing is submitted.":(p.enabled?"Rules saved. New matches can be prepared every 30 minutes. Review each draft before applying.":"Set your match score and draft limit, then turn on preparation. No application is submitted.")}catch(e){if(e.status===401&&!googleSessionActive)clearPortalToken();note.textContent=e.message;document.getElementById("automationEnabled").disabled=true;document.getElementById("saveAutomationBtn").disabled=true;document.getElementById("runAutomationBtn").disabled=true}}
async function loadPrivateSetup(){const epoch=authEpoch;try{const session=await api("/api/auth/session");if(epoch!==authEpoch)return;googleSessionActive=!!session.authenticated;if(googleSessionActive)clearPortalToken()}catch(e){googleSessionActive=false}const token=getPortalToken();if(!token&&!googleSessionActive){resetPrivateWorkspace();profileReady=false;document.getElementById("profilePanel").open=true;document.getElementById("profileConnect").style.display="";document.getElementById("profileForm").style.display="none";document.getElementById("changeTokenBtn").style.display="none";document.getElementById("signOutGoogleBtn").style.display="none";document.getElementById("profileState").textContent="CONNECT REQUIRED";document.getElementById("profileState").className="pill setup";document.getElementById("saveAutomationBtn").disabled=true;document.getElementById("runAutomationBtn").disabled=true;document.getElementById("autoApplyBtn").disabled=true;await loadAutomationSettings();return}try{const p=await privateApi("/api/profile");showProfile(p)}catch(e){if(e.status===401&&!googleSessionActive)clearPortalToken();document.getElementById("profileConnect").style.display="";document.getElementById("profileForm").style.display="none";document.getElementById("changeTokenBtn").style.display="none";document.getElementById("signOutGoogleBtn").style.display="none";document.getElementById("profileState").textContent=e.status===503?"SERVER SETUP PENDING":"CONNECT REQUIRED";document.getElementById("profileState").className="pill setup";document.getElementById("profileConnectNote").textContent=e.status===503?"Private access is not ready on the server yet. Try again shortly.":e.message;profileReady=false;document.getElementById("saveAutomationBtn").disabled=true;document.getElementById("runAutomationBtn").disabled=true;document.getElementById("autoApplyBtn").disabled=true;document.getElementById("automationNote").textContent="Sign in with Google or connect with your private access key to use draft preparation."}}
async function setupGoogleSignIn(){const note=document.getElementById("googleSignInNote"),fallback=document.querySelector("#profileConnect details");try{const config=await api("/api/auth/google/config");if(!config.enabled){note.textContent=config.reason+" Authorized redirect URI: "+window.location.origin+"/api/auth/google/session";fallback.open=true;return}note.textContent="Use the same Google email saved in your profile.";const script=document.createElement("script");script.src="https://accounts.google.com/gsi/client";script.async=true;script.defer=true;script.onload=()=>{if(!window.google||!google.accounts||!google.accounts.id){note.textContent="Google sign-in could not load. Try the private access key below.";fallback.open=true;return}google.accounts.id.initialize({client_id:config.client_id,ux_mode:"popup",nonce:config.nonce,callback:async(response)=>{try{note.textContent="Verifying your Google sign-in…";await api("/api/auth/google/session",{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json"},body:JSON.stringify({credential:response.credential,login_nonce:config.nonce})});await loadAll();toast("Signed in with Google.","success");}catch(e){note.textContent=e.message;toast(e.message,"error");}}});google.accounts.id.renderButton(document.getElementById("googleSignInButton"),{theme:"outline",size:"large",shape:"rectangular",text:"continue_with",width:280});};script.onerror=()=>{note.textContent="Google sign-in could not load. Try the private access key below.";fallback.open=true;};document.head.appendChild(script)}catch(e){note.textContent="Google sign-in setup could not be checked. You can still use your private access key below.";fallback.open=true}}
function showGoogleSignInResult(){const result=new URLSearchParams(window.location.search).get("google_signin");if(!result)return;const messages={success:"Signed in with Google.",email_mismatch:"Use the same Google email saved in your Job Hunter profile.",not_configured:"Google sign-in is not configured yet. Use your private access key below.",failed:"Google sign-in did not finish. Please try again."};toast(messages[result]||messages.failed,result==="success"?"success":"error");const url=new URL(window.location.href);url.searchParams.delete("google_signin");history.replaceState({},"",url.pathname+url.search+url.hash)}
async function saveAutomationSettings(){const btn=document.getElementById("saveAutomationBtn");if(document.getElementById("automationEnabled").checked&&!profileReady){toast("Complete your profile and upload a PDF resume first","error");switchTab("settings");document.getElementById("profilePanel").scrollIntoView({behavior:"smooth"});return}btn.disabled=true;try{const payload={enabled:document.getElementById("automationEnabled").checked,min_score:Number(document.getElementById("automationMinScore").value),max_per_run:Number(document.getElementById("automationMaxRun").value),pause_on_captcha_otp:true,pause_on_unknown_required_answer:true,pause_on_legal_declaration:true};const p=await privateApi("/api/automation/settings",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});toast("Rules saved · draft-only mode","success");document.getElementById("automationState").textContent=p.enabled?"ON · DRAFTS ONLY":"OFF · DRAFTS ONLY";document.getElementById("automationState").className="pill "+(p.enabled?"ready":"setup");await loadAutomationSettings()}catch(e){toast("Could not save rules: "+e.message,"error")}finally{btn.disabled=!profileReady}}
async function runAutomationPreparation(){if(!profileReady){toast("Complete your profile and upload a PDF resume first","error");switchTab("settings");return}const btn=document.getElementById("runAutomationBtn");btn.disabled=true;btn.textContent="Preparing…";try{const p=await privateApi("/api/automation/prepare",{method:"POST"});const summary=(p.prepared||[]).slice(0,10).map(x=>"• "+(x.title||"Role")+" — "+(x.company||"Company")+" (score "+(x.match_score??"—")+")").join("\n");window.alert("Draft preparation complete\n\nReady for review: "+(p.prepared_count||0)+"\nMinimum match: "+p.threshold+"\n\n"+(summary||"No eligible jobs found.")+"\n\nNothing was submitted.");toast("Prepared "+(p.prepared_count||0)+" drafts; no applications submitted","success")}catch(e){toast("Draft preparation failed: "+e.message,"error")}finally{btn.disabled=!profileReady||!document.getElementById("automationEnabled").checked;btn.textContent="Prepare drafts now"}}
async function runAutoApplyQueue(){if(!profileReady){toast("Complete your profile and upload a PDF resume first","error");switchTab("settings");return}const btn=document.getElementById("autoApplyBtn");btn.disabled=true;btn.textContent="Preparing…";try{const result=await privateApi("/api/auto-apply/queue",{method:"POST"});const items=result.prepared||[];toast("Prepared "+(result.prepared_count||0)+" drafts for review","success");const summary=items.slice(0,12).map(x=>"• "+(x.title||"Role")+" — "+(x.company||"Company")+" (score "+(x.match_score??"—")+")"+(x.ai_assisted?" [AI-assisted]":" [template]")).join("\n");window.alert("Drafts ready for review\n\nPrepared: "+(result.prepared_count||0)+"\nMatch threshold: "+result.threshold+"/100\n\n"+(summary||"No eligible jobs found.")+"\n\nReview each draft and apply on the employer site yourself. Nothing was submitted.")}catch(e){toast("Could not prepare drafts: "+e.message,"error")}finally{btn.disabled=!profileReady;btn.textContent="Prepare drafts"}}
async function prepareApply(jobId){if(!profileReady){toast("Complete your profile and upload a PDF resume first","error");switchTab("settings");return}try{const draft=await privateApi("/api/applications/draft/"+jobId,{method:"POST"});const guidance=(draft.resume_guidance||[]).join("\n");document.getElementById("draftTitle").textContent=draft.tailored_headline||"Application draft";document.getElementById("draftMeta").textContent="Draft only. Nothing was submitted. Edit this before you use it.";document.getElementById("draftBody").textContent=(draft.cover_letter||"")+"\n\n---\n"+guidance;document.getElementById("draftDialog").showModal();toast("Draft ready for review","success");loadJobs();}catch(e){toast("Could not prepare draft: "+e.message,"error")}}
let outreachContacts=[],outreachDrafts=[],outreachCurrentDraft=null,outreachVerifyId=null;
async function loadOutreach(){if(!privateConnectionReady())return;try{const [status,contacts,drafts,jobs]=await Promise.all([privateApi('/api/outreach/status'),privateApi('/api/outreach/contacts'),privateApi('/api/outreach/drafts'),privateApi('/api/jobs?limit=500&min_score=0')]);outreachContacts=contacts.items||[];outreachDrafts=drafts.items||[];document.getElementById('outreachStatus').textContent=(status.prospeo_configured?'Prospeo configured. ':'Prospeo needs PROSPEO_API_KEY in secure Render settings. ')+(status.apollo_configured?'Apollo key present (access may be restricted). ':'')+(status.gmail.send_authorized?'Gmail sending authorized.':'Enable Gmail sending and approve Google permission before sending.')+(status.scheduler_enabled?'':' Automatic sending is currently paused; approved emails can be sent manually.');document.getElementById('outreachGmailBtn').textContent=status.gmail.send_authorized?'Reconnect Gmail':'Enable Gmail sending';document.getElementById('outreachDailyLimit').value=status.policy.daily_limit;document.getElementById('outreachAutoApproved').checked=!!status.policy.auto_send_approved;const select=document.getElementById('outreachJob'),current=select.value;select.innerHTML='<option value="">Choose a discovered job</option>'+(jobs.items||[]).map(j=>'<option value="'+Number(j.id)+'">'+esc(j.title)+' — '+esc(j.company)+'</option>').join('');if([...select.options].some(x=>x.value===current))select.value=current;document.getElementById('outreachContacts').innerHTML=outreachContacts.map(c=>'<tr><td>'+esc(c.name)+'<div class="job-meta">'+esc(c.email)+'</div></td><td>'+esc(c.company)+'<div class="job-meta">'+esc(c.title)+'</div></td><td>'+(c.suppressed?'Do not contact':c.verified?'Reviewed':esc(c.email_status)+' email status; responsibility unverified')+'</td><td>'+(c.suppressed?'':('<button class="btn btn-ghost btn-sm" onclick="openContactVerification('+Number(c.id)+')">Verify</button> <button class="btn btn-primary btn-sm" onclick="createOutreachDraft('+Number(c.id)+')">Prepare email</button> <button class="btn btn-ghost btn-sm" onclick="suppressOutreachContact('+Number(c.id)+')">Do not contact</button>'))+'</td></tr>').join('')||'<tr><td colspan="4">Search a contact provider or add a sourced business contact.</td></tr>';if(typeof renderFocusedQueue==='function')renderFocusedQueue();else{document.getElementById('outreachQueue').innerHTML=outreachDrafts.map(d=>'<tr><td>'+esc(d.recipient_email)+'</td><td>'+esc(d.subject)+'</td><td>'+esc(d.state==='sent'?'Accepted by Gmail':d.state)+(d.error?'<div class="job-meta">'+esc(d.error)+'</div>':'')+'</td><td><button class="btn btn-ghost btn-sm" onclick="openOutreachDraft('+Number(d.id)+')">Review</button></td></tr>').join('')||'<tr><td colspan="4">No email drafts yet. Nothing will send without your approval.</td></tr>'}}catch(e){document.getElementById('outreachStatus').textContent=e.message}}
async function connectOutreachGmail(){try{const r=await privateApi('/api/outreach/gmail/connect',{method:'POST'});location.assign(r.url)}catch(e){toast(e.message,'error')}}
async function searchApollo(){try{document.getElementById('apolloResults').textContent='Searching recruiter roles…';const r=await privateApi('/api/outreach/apollo/search',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({company_domain:document.getElementById('outreachDomain').value.trim()})});document.getElementById('apolloResults').innerHTML=''+(r.items||[]).map(p=>'<div class="conn-card"><div><strong>'+esc(p.name)+'</strong><div>'+esc(p.title)+' · '+esc(p.company)+'</div></div><button class="btn btn-ghost btn-sm" data-apollo-id="'+esc(p.apollo_id)+'" onclick="revealApolloEmail(this.dataset.apolloId,this)">Reveal work email — uses credits</button></div>').join('');if(!(r.items||[]).length)document.getElementById('apolloResults').textContent='No recruiter leads returned for that employer.'}catch(e){document.getElementById('apolloResults').textContent=e.message}}
async function revealApolloEmail(id,button){if(button?.disabled)return;if(!confirm('Reveal this work email using Apollo enrichment credits? Personal emails and phone numbers will not be requested.'))return;if(button)button.disabled=true;try{await privateApi('/api/outreach/apollo/enrich',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({apollo_id:id,confirm_credit_use:true})});toast('Contact saved. Verify current employer and recruiting responsibility before approval.','success');await loadOutreach()}catch(e){toast(e.message,'error')}finally{if(button)button.disabled=false}}
async function addOutreachContact(){try{await privateApi('/api/outreach/contacts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:document.getElementById('contactName').value,email:document.getElementById('contactEmail').value,company:document.getElementById('contactCompany').value,title:document.getElementById('contactRole').value,source_url:document.getElementById('contactSource').value})});toast('Unverified contact saved','success');await loadOutreach()}catch(e){toast(e.message,'error')}}
function openContactVerification(id){const c=outreachContacts.find(x=>x.id===id);if(!c)return;outreachVerifyId=id;document.getElementById('verifyContactSummary').textContent=c.name+' · '+c.email+' · '+c.company+' · '+c.title;document.getElementById('verifyContactSource').href=c.source_url;['verifyEmail','verifyEmployer','verifyRole'].forEach(x=>document.getElementById(x).checked=false);document.getElementById('verifyNote').value='';document.getElementById('outreachVerifyDialog').showModal()}
async function verifyOutreachContact(){try{await privateApi('/api/outreach/contacts/'+outreachVerifyId+'/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email_confirmed:document.getElementById('verifyEmail').checked,employer_confirmed:document.getElementById('verifyEmployer').checked,role_confirmed:document.getElementById('verifyRole').checked,note:document.getElementById('verifyNote').value})});document.getElementById('outreachVerifyDialog').close();await loadOutreach()}catch(e){toast(e.message,'error')}}
async function suppressOutreachContact(id){try{await privateApi('/api/outreach/contacts/'+id+'/suppress',{method:'POST'});toast('Future emails to this contact stopped','success');await loadOutreach()}catch(e){toast(e.message,'error')}}
async function createOutreachDraft(id){const job=Number(document.getElementById('outreachJob').value);if(!job){toast('Choose a discovered job first','error');return}try{const d=await privateApi('/api/outreach/drafts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({contact_id:id,job_id:job})});await loadOutreach();openOutreachDraft(d.id)}catch(e){toast(e.message,'error')}}
function openOutreachDraft(id){const d=outreachDrafts.find(x=>x.id===id);if(!d)return;outreachCurrentDraft=d;document.getElementById('outreachEnvelope').textContent='From: '+d.sender_email+' → To: '+d.recipient_email;document.getElementById('outreachSubject').value=d.subject;document.getElementById('outreachBody').value=d.body;document.getElementById('approveEmailReview').checked=false;document.getElementById('approveEmailRelevance').checked=false;document.getElementById('outreachDraftState').textContent='Status: '+d.state+(d.error?' · '+d.error:'');document.getElementById('outreachSendBtn').disabled=d.state!=='approved';document.getElementById('outreachComposeDialog').showModal()}
function outreachDirty(){document.getElementById('outreachSendBtn').disabled=true;document.getElementById('approveEmailReview').checked=false;document.getElementById('approveEmailRelevance').checked=false;document.getElementById('outreachDraftState').textContent='Edits need saving and fresh approval.'}
async function saveOutreachDraft(){
  const id=outreachCurrentDraft.id,subject=document.getElementById('outreachSubject').value,body=document.getElementById('outreachBody').value;
  const button=document.querySelector('#outreachComposeDialog button[onclick="saveOutreachDraft()"]');
  if(button.disabled)return false;button.disabled=true;
  document.getElementById('outreachDraftState').textContent='Saving changes…';
  try{const d=await privateApi('/api/outreach/drafts/'+id+'/edit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({subject,body})});
    await loadOutreach();
    if(outreachCurrentDraft?.id===id){outreachCurrentDraft=d;outreachDirty();if(document.getElementById('outreachSubject').value===subject&&document.getElementById('outreachBody').value===body)document.getElementById('outreachDraftState').textContent='Saved as draft; approval required.';}
    return true;
  }catch(e){toast(e.message,'error');return false;}finally{button.disabled=false;}
}
async function approveOutreachDraft(){if(!document.getElementById('approveEmailReview').checked||!document.getElementById('approveEmailRelevance').checked){toast('Review the email and confirm recipient relevance first','error');return}try{if(document.getElementById('outreachSubject').value!==outreachCurrentDraft.subject||document.getElementById('outreachBody').value!==outreachCurrentDraft.body){toast('Save edits, then review and approve the saved email','error');return}outreachCurrentDraft=await privateApi('/api/outreach/drafts/'+outreachCurrentDraft.id+'/approve',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmed:true,recipient_relevance_confirmed:true})});document.getElementById('outreachDraftState').textContent='Approved. Automatic sending applies only if you enabled it.';document.getElementById('outreachSendBtn').disabled=false;await loadOutreach()}catch(e){toast(e.message,'error')}}
async function sendOutreachDraft(){document.getElementById('outreachSendBtn').disabled=true;try{const d=await privateApi('/api/outreach/drafts/'+outreachCurrentDraft.id+'/send',{method:'POST'});outreachCurrentDraft=d;document.getElementById('outreachDraftState').textContent=d.state==='sent'?'Accepted by Gmail; inbox delivery is not independently verified.':d.state+' · '+d.error;await loadOutreach()}catch(e){document.getElementById('outreachDraftState').textContent=e.message;toast(e.message,'error')}}
async function saveOutreachPolicy(){try{await privateApi('/api/outreach/policy',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({daily_limit:Number(document.getElementById('outreachDailyLimit').value),auto_send_approved:document.getElementById('outreachAutoApproved').checked})});toast('Outreach rules saved','success');await loadOutreach()}catch(e){toast(e.message,'error')}}
function setScore(val,el){document.getElementById("filterScore").value=val;document.querySelectorAll(".chip").forEach(c=>c.classList.remove("active"));el.classList.add("active");loadJobs()}
function resetFilters(){document.getElementById("jobSearch").value="";document.getElementById("filterCountry").value="";document.getElementById("filterSource").value="";document.getElementById("filterScore").value=gulfOpenView?"0":"65";if(!gulfOpenView)document.getElementById("filterPosted").value="3";document.getElementById("filterStatus").value="";document.querySelectorAll(".chip").forEach(c=>c.classList.toggle("active",c.dataset.score===document.getElementById("filterScore").value));loadJobs()}
async function loadCoverage(){if(!privateConnectionReady())return;try{const stats=await privateApi('/api/stats');for(const [id,rows,key] of [['countryCoverage',stats.by_country||[],'country'],['sourceCoverage',stats.by_source||[],'source']]){document.getElementById(id).innerHTML=rows.map(row=>'<div class="coverage-item"><strong>'+esc(row[key])+'</strong><span>'+Number(row.count||0)+' listings</span></div>').join('')||'<span>No data yet</span>'}}catch(e){console.warn('coverage',e)}}
async function runHunt(){const btn=document.getElementById("huntBtn");btn.disabled=true;btn.textContent="Running…";toast("Job hunt started");try{const res=await privateApi("/api/hunt",{method:"POST"});if(res.status==="already_running"){toast("A hunt is already running","error");}else{const issues=(res.errors||[]).length;toast("Hunt done · "+(res.new_jobs||0)+" new"+(issues?(" · "+issues+" source issues"):""),issues?"error":"success");}await loadAll()}catch(e){toast("Hunt failed: "+e.message,"error")}finally{btn.disabled=false;btn.textContent="⌕ Run job hunt"}}
async function loadWorkspaceData(loadPreferences=false){
  if(!privateConnectionReady())return;
  const tab=location.hash.slice(1);
  const activeView=tab==='applications'?loadApplications():tab==='outreach'?loadOutreach():Promise.resolve();
  const background=async()=>{
    if(loadPreferences)await Promise.all([loadSearchPreferences(),loadAutomationSettings()]);
    if(privateConnectionReady())await Promise.all([loadStats(),loadSources(),loadJobs(),loadCoverage(),loadMarketSummary(),loadReadiness()]);
  };
  await Promise.all([activeView,background()]);
  renderWorkspaceState();
}
async function loadAll(){await loadPrivateSetup();if(privateConnectionReady())await loadWorkspaceData(true);else resetPrivateWorkspace()}


let applicationItems=[];
function renderWorkspaceState(){const ready=profileReady,connected=privateConnectionReady();document.getElementById('workspaceNoticeTitle').textContent=ready?'Your profile is ready':connected?'Finish your private profile':'Make this workspace yours';document.getElementById('workspaceNoticeText').textContent=ready?'Choose a role, verify the right recruiter and review your email before sending.':connected?'Add your real experience and upload a text-based PDF to unlock accurate drafts.':'Connect your profile to prepare accurate applications and manage recruiter outreach.';const button=document.getElementById('workspaceNoticeAction');button.textContent=ready?'Open outreach →':'Open profile →';button.onclick=()=>switchTab(ready?'outreach':'settings');document.getElementById('workspaceAccess').textContent=connected?'Private connection active':'Connect to get started';if(connected){const name=document.getElementById('profileName').value||'Your workspace';document.getElementById('workspaceName').textContent=name;document.getElementById('userInitials').textContent=name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()}else{document.getElementById('workspaceName').textContent='Your private workspace';document.getElementById('userInitials').textContent='JH'}}
async function loadApplications(){if(!privateConnectionReady())return;const body=document.getElementById('applicationsBody');try{const data=await privateApi('/api/applications');applicationItems=data.items||[];document.getElementById('applicationBadge').textContent=applicationItems.length;const options=['prepared','ready_for_review','applied_manually','interview','rejected','offer','withdrawn'];body.innerHTML=applicationItems.map(d=>'<tr><td><strong>'+esc(d.job?.title||'Role')+'</strong><div class="job-meta">'+esc(d.job?.location||'')+'</div></td><td>'+esc(d.job?.company||'')+'</td><td><select aria-label="Application status" onchange="updateApplicationStatus('+Number(d.id)+',this.value)">'+options.map(status=>'<option value="'+status+'"'+(d.status===status?' selected':'')+'>'+esc(status.replaceAll('_',' '))+'</option>').join('')+'</select></td><td><button class="btn btn-ghost btn-sm" onclick="viewApplicationDraft('+Number(d.id)+')">View draft</button></td></tr>').join('')||'<tr><td colspan="4"><div class="empty-state"><h3>No application drafts yet</h3><p>Start with a job match and prepare your first application.</p><button class="btn btn-primary" onclick="switchTab(&quot;jobs&quot;)">Browse job matches</button></div></td></tr>'}catch(e){body.innerHTML='<tr><td colspan="4"><div class="empty-state"><h3>Connect your private profile</h3><p>'+esc(e.message)+'</p><button class="btn btn-primary" onclick="switchTab(&quot;settings&quot;)">Open profile</button></div></td></tr>'}}
async function updateApplicationStatus(id,status){try{await privateApi('/api/applications/'+id+'/status',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({status})});toast('Application status updated','success');loadApplications();loadStats()}catch(e){toast(e.message,'error')}}
function viewApplicationDraft(id){const draft=applicationItems.find(x=>x.id===id);if(!draft)return;document.getElementById('draftTitle').textContent=draft.tailored_headline;document.getElementById('draftMeta').textContent='Review your verified facts before using this draft. No application was submitted.';document.getElementById('draftBody').textContent=draft.cover_letter+'\n\n'+(draft.resume_guidance||[]).join('\n');document.getElementById('draftDialog').showModal()}
function labelResponsiveTables(){document.querySelectorAll('.table-wrap table').forEach(table=>{const headers=[...table.querySelectorAll('thead th')].map(x=>x.textContent);table.querySelectorAll('tbody tr').forEach(row=>{if(row.children.length!==headers.length)return;[...row.children].forEach((cell,index)=>cell.dataset.label=headers[index])})})}
document.querySelectorAll('.table-wrap tbody').forEach(body=>new MutationObserver(labelResponsiveTables).observe(body,{childList:true}));setInterval(()=>renderWorkspaceState(),1500);

async function loadMarketSummary(){if(!privateConnectionReady())return;try{const settings=await privateApi('/api/settings'),countries=settings.target_countries||[],gulf=['United Arab Emirates','Saudi Arabia','Qatar','Kuwait','Oman','Bahrain'];let places=countries.includes('India')?(settings.preferred_locations||[]).map(x=>x==='Uttar Pradesh'?'UP':x):[];if(countries.includes('India')&&!places.length)places.push('India');if(gulf.every(x=>countries.includes(x)))places.push('Gulf');else places.push(...countries.filter(x=>gulf.includes(x)));places.push(...countries.filter(x=>x!=='India'&&!gulf.includes(x)));document.getElementById('targetRegionSummary').textContent=places.join(' · ')||'Choose your target markets'}catch(e){document.getElementById('targetRegionSummary').textContent='Target markets unavailable'}}
async function copyApplicationDraft(){try{await navigator.clipboard.writeText(document.getElementById('draftBody').textContent);toast('Draft copied. Review it before using it.','success')}catch(e){toast('Copy was unavailable. Select the draft text to copy it manually.','error')}}


/* Operational readiness: live backend truth, no invented application counts. */
async function loadReadiness(){
  if(!privateConnectionReady())return;
  const target=(id,v)=>{const el=document.getElementById(id);if(el)el.textContent=v};
  try{
    const data=await privateApi('/api/operational-readiness');
    const last=data.last_hunt||{};
    const found=Number(data.jobs_in_current_window||0);
    target('missionDiscovery',found+' matching jobs');
    target('missionDiscoveryNote',last.finished_at?'Last hunt '+ago(last.finished_at)+' · '+Number(last.fetched||0)+' fetched':'Run a hunt to begin');
    target('missionResume',data.resume_uploaded?'Resume ready':'Resume needed');
    target('missionResumeNote',data.resume_uploaded?'PDF uploaded in your profile':'Upload your latest PDF');
    target('missionApply',data.automatic_submission_enabled?'Auto-submit enabled':'Drafts only');
    target('missionApplyNote',data.automatic_submission_enabled?'Check confirmed application outcomes':'No automatic form submissions');
    target('missionGmail',data.gmail_connected?'Connected':'Not connected');
    target('missionGmailNote',data.gmail_connected?'Job-alert integration connected':'Connect to read job alerts');
    const blockers=Array.isArray(data.blockers)?data.blockers:[];
    const lastErrors=last.errors;
    let errorCount=0;
    try{const e=typeof lastErrors==='string'?JSON.parse(lastErrors):lastErrors;if(Array.isArray(e))errorCount=e.length}catch(_){}
    let priority=blockers.find(x=>!/submission/i.test(x));
    if(!priority&&!data.gmail_connected)priority='Connect Gmail job alerts to expand discovery coverage.';
    if(!priority&&found===0)priority='No matching recent jobs. Check source health and widen filters.';
    if(!priority&&errorCount)priority=errorCount+' source issue(s) in the latest hunt. Check Connections.';
    if(!priority)priority='Review matching roles and prepare accurate application drafts.';
    target('missionAction',priority);
    target('missionTimestamp',last.finished_at?'Last backend run · '+ago(last.finished_at):'Awaiting first hunt');
  }catch(err){
    target('missionDiscovery','Unavailable');
    target('missionDiscoveryNote','Could not reach backend');
    target('missionResume','Unknown');
    target('missionResumeNote','Could not verify resume status');
    target('missionApply','Unknown');
    target('missionApplyNote','Could not verify application policy');
    target('missionGmail','Unknown');
    target('missionGmailNote','Could not verify Gmail connection');
    target('missionAction','Backend status could not be verified. Check the API and try again.');
    target('missionTimestamp','Connection check failed');
  }
}
setInterval(loadReadiness,180000);

showGoogleSignInResult();setupGoogleSignIn();resetPrivateWorkspace();switchTab(location.hash.slice(1)||'jobs');loadAll();
setInterval(()=>{if(privateConnectionReady()){loadStats();loadSources()}},180000);
